parts.text:
{
  "feasible": true,
  "summary": "Se añade la página de resumen en /resumen con tarjetas y contadores para el número total de clientes, los presupuestos enviados y el importe pendiente de cobro de las facturas pendientes. Se incluye también en el menú de navegación lateral mediante el enlace correspondiente y se añade a la lista de páginas E2E para su captura.",
  "assumptions": [
    "Los presupuestos enviados corresponden al recuento de presupuestos cuyo estado es 'sent'.",
    "El importe pendiente de cobro se calcula sumando el total de todas las facturas cuyo estado es 'pending'."
  ],
  "tasks": [
    {
      "title": "Añadir página de resumen y consultas de métricas",
      "description": "Crea queries.ts en src/app/(crm)/resumen/ queries con consultas para contar clientes, presupuestos enviados y sumar importes de facturas pendientes. Crea page.tsx en src/app/(crm)/resumen/ utilizando Suspense y componentes con data-testid summary-card, client-count, sent-quotes-count e pending-amount.",
      "files": [
        "src/app/(crm)/resumen/page.tsx",
        "src/app/(crm)/resumen/queries.ts",
        "e2e/pages.ts"
      ],
      "references": [
        "src/app/(crm)/facturas/queries.ts",
        "src/app/(crm)/clientes/page.tsx",
        "src/app/(crm)/facturas/page.tsx"
      ],
      "acceptanceCriteria": [
        {
          "id": "c1",
          "type": "e2e",
          "text": "La página de resumen carga correctamente y muestra el título y las tarjetas de métricas.",
          "testIds": [
            "nav-resumen",
            "page-title",
            "summary-card"
          ]
        },
        {
          "id": "c2",
          "type": "e2e",
          "text": "Se muestra el recuento de clientes y presupuestos enviados en las tarjetas correspondientes.",
          "testIds": [
            "nav-resumen",
            "client-count",
            "sent-quotes-count"
          ]
        },
        {
          "id": "c3",
          "type": "e2e",
          "text": "Se muestra el importe pendiente de cobro en la tarjeta de pendientes.",
          "testIds": [
            "nav-resumen",
            "pending-amount"
          ]
        }
      ]
    }
  ]
}
